import java.io.*;
import java.util.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static String next() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = read();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt(), k = nextInt();
        // For each value v: best gain of a segment ending at its last occurrence, and the k count then.
        final int MAXV = 200001;
        long[] gain = new long[MAXV + 1], at = new long[MAXV + 1];
        boolean[] seen = new boolean[MAXV + 1];
        long count = 0, best = 0;
        for (int i = 0; i < n; i++) {
            int v = nextInt();
            if (v == k) {
                count++;
                continue;
            }
            long old = seen[v] ? gain[v] : 0, previous = seen[v] ? at[v] : count;
            // Kadane: extend (paying for the k's in between) or restart at this v.
            long g = Math.max(1, old - (count - previous) + 1);
            gain[v] = g;
            at[v] = count;
            seen[v] = true;
            best = Math.max(best, g);
        }
        System.out.println(count + best);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
)

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n, k := int(nextInt()), nextInt()
	// For each value v: best gain of a segment ending at its last occurrence, and the k count then.
	const maxV = 200001
	gain := make([]int64, maxV+1)
	at := make([]int64, maxV+1)
	seen := make([]bool, maxV+1)
	var count, best int64
	for i := 0; i < n; i++ {
		v := nextInt()
		if v == k {
			count++
			continue
		}
		old, previous := int64(0), count
		if seen[v] {
			old, previous = gain[v], at[v]
		}
		// Kadane: extend (paying for the k's in between) or restart at this v.
		g := max(1, old-(count-previous)+1)
		gain[v], at[v], seen[v] = g, count, true
		best = max(best, g)
	}
	fmt.Println(count + best)
}

var data []byte
var pos int

func skipSpace() {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
}

func nextToken() []byte {
	skipSpace()
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func nextInt() int64 {
	skipSpace()
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}
